\subsection{Example 1: A Probability Theory Problem}
\begin{examplebox}[Problem Statement]
Consider a sequence $X_{1}, X_{2}, \ldots$, of i.i.d. random variables, each having an exponential distribution with parameter 1. Let $M_{n}:=\max \left\{X_{1}, \ldots, X_{n}\right\}$. \\
(a) Let $Y_{n}=X_{n} \mathbf{1}\left\{X_{n} \leq \log n\right\}$ denote a truncated exponential, i.e., $Y_{n}=X_{n}$ if $X_{n} \leq \log n$ and equals zero otherwise. Prove that $Y_{n} \neq X_{n}$, i.o., almost surely. \\
(b) Prove that $M_{n} / \log n \rightarrow 1$ almost surely as $n \rightarrow \infty$, where $\log$ denotes the natural logarithm.
\end{examplebox}

\begin{examplebox}[Reference Solution]
(a) Consider
$$
\sum_{n=1}^{\infty} \mathrm{P}\left\{X_{n} >\log n\right\}=\sum_{n=1}^{\infty}\frac{1}{n}=\infty.
$$
By Borel-Cantelli Lemma, it follows that
$$
\mathrm{P}\left\{X_{n} > \log n \text { i.o.}\right\}=1
$$
With $Y_{n} = X_{n} 1\left\{\left|X_{n}\right| \leq \log n\right\}$, it is clear that
$$
\left\{\omega: X_{n}(\omega) > \log n \text { i.o.}\right\} \subseteq\left\{\omega: Y_{n}(\omega) \ne X_{n}(\omega) \text { i.o.}\right\}.
$$
Since the event on the left-hand side has probability one, so does the event on the righthand side. That is, $Y_{n} \ne X_{n}$ infinitely often, almost surely.\\
\vspace{0.5em}

\noindent (b) Fix $\varepsilon>0$. We first show that 
$$
\left\{M_{n} \leq(1+\varepsilon) \log n \text{ ev.}\right\}=\left\{X_{n} \leq(1+\varepsilon) \log n \text{ ev.}\right\}
$$
For every $\omega \in\left\{X_{n}(\omega) \leq(1+\varepsilon) \log n \text{ ev.}\right\}$, we have
$$
\exists N(\omega) \in \NN, \quad X_{n}(\omega) \leq(1+\varepsilon) \log n \quad \text { for all } n \geq N(\omega).
$$
It follows that
$$
\max _{1 \leq i \leq n} X_{i}(\omega) \leq(1+\varepsilon) \log n \quad \text { for all } n>\max \left\{N(\omega), e^{\frac{1}{1+\varepsilon} \max _{1 \leq i \leq N(\omega)} X_{i}(\omega)}\right\}.
$$
In other words,
$$
M_{n}(\omega) \leq(1+\varepsilon) \log n, \text { eventually. }
$$
Therefore, $\left\{X_{n} \leq(1+\varepsilon) \log n \text{ ev.}\right\}\subseteq\left\{M_{n} \leq(1+\varepsilon) \log n \text{ ev.}\right\}$. It is trivial to see that 
$$
\left\{M_{n} \leq(1+\varepsilon) \log n \text{ ev.}\right\} \subseteq\left\{X_{n} \leq(1+\varepsilon) \log n \text{ ev.}\right\},
$$
so the two events are in fact equivalent. Consequently, their complements are equivalent, that is,
$$
\left\{M_{n}>(1+\varepsilon) \log n \text { i.o.}\right\}=\left\{X_{n}>(1+\varepsilon) \log n \text { i.o.}\right\}.
$$
By Borel-Cantelli Lemma,
$$
\sum_{n=1}^{\infty} \mathrm{P}\left\{X_{n} \geq(1+\varepsilon) \log n\right\}=\sum_{n=1}^{\infty} \frac{1}{n^{1+\varepsilon}}<\infty \Rightarrow \mathrm{P}\left\{X_{n} \geq(1+\varepsilon) \log n \text { i.o.}\right\}=0.
$$
Therefore,
\begin{equation}\label{eq:probtheory1}
\mathrm{P}\left\{\frac{M_{n}}{\log n}>1+\varepsilon \text { i.o.}\right\}=0, \quad \forall \varepsilon>0.
\end{equation}
Recall that
$$
\mathrm{P}\left(M_{n} \leq x\right)=\mathrm{P}\left(\max _{1 \leq i \leq n} X_{i} \leq x\right)=\prod_{i=1}^{n} \mathrm{P}\left(X_{i} \leq x\right)=\left(1-e^{-x}\right)^{n},
$$
so for large $n$,
$$
\mathrm{P}\left\{\frac{M_{n}}{\log n}<1-\varepsilon\right\}=\mathrm{P}\left\{M_{n}<(1-\varepsilon) \log n\right\}=\left(1-e^{-(1-\varepsilon) \log n}\right)^{n}=\left(1-\frac{1}{n^{1-\varepsilon}}\right)^{n} \approx e^{-n^{\varepsilon}}.
$$
Therefore,
$$
\sum_{n=1}^{\infty} \mathrm{P}\left\{\frac{M_{n}}{\log n}<1-\varepsilon\right\}<\infty.
$$
By Borel-Cantelli Lemma,
\begin{equation}\label{eq:probtheory2}
\mathrm{P}\left\{\frac{M_{n}}{\log n}<1-\varepsilon \text { i.o.}\right\}=0, \quad \forall \varepsilon>0.
\end{equation}
Combining \eqref{eq:probtheory1} and \eqref{eq:probtheory2}, we conclude that $M_{n} / \log n \rightarrow 1$ almost surely as $n \rightarrow \infty$.
\end{examplebox}

\begin{examplebox}[GPT-4o's Response]
To solve this problem rigorously, we will work through each part separately, providing detailed explanations and proofs.
\vspace{1em}

\noindent \textbf{(a) $\ Y_{n} \neq X_{n}$ i.o., almost surely.}

\underline{Definitions and Setup}:
The sequence $\{X_n\}_{n \geq 1}$ consists of i.i.d. random variables following an exponential distribution with parameter 1. The exponential distribution has a cumulative distribution function (CDF) given by $F(x) = 1 - e^{-x}$ for $x \geq 0$. The random variable $Y_n = X_n \mathbb{I}\{X_n \leq \log n\}$ indicates that $Y_n = X_n$ if $X_n \leq \log n$, and $Y_n = 0$ otherwise. We need to show that $Y_n \neq X_n$ occurs infinitely often (i.o.), almost surely.

\underline{Approach}:
For $Y_n \neq X_n$, it must be that $X_n > \log n$. We will use the Borel-Cantelli lemma to show that this event ($\{X_n > \log n\}$) happens infinitely often with probability 1.

\underline{Probability of Event}:
The probability that $X_n > \log n$ is given by:
\[ P(X_n > \log n) = 1 - P(X_n \leq \log n) = e^{-\log n} = \frac{1}{n}. \]

\underline{Series Sum}:
Consider the series:
\[ \sum_{n=1}^{\infty} P(X_n > \log n) = \sum_{n=1}^{\infty} \frac{1}{n}, \]
which is the harmonic series and diverges.

\underline{Application of Borel-Cantelli Lemma}:
Since the series diverges, by the Borel-Cantelli lemma, $P(X_n > \log n \ \text{i.o.}) = 1$. Therefore, $P(Y_n \neq X_n \ \text{i.o.}) = 1$, which means $Y_n \neq X_n$ happens infinitely often almost surely.
\vspace{1em}

\noindent \textbf{(b) $M_n / \log n \rightarrow 1$ almost surely as $n \rightarrow \infty$.}

\underline{Definitions and Setup}:
The random variable $M_n = \max\{X_1, X_2, \ldots, X_n\}$ is the maximum of the first $n$ i.i.d. exponentially distributed random variables. We aim to show that $\frac{M_n}{\log n} \to 1$ almost surely as $n \to \infty$.

\underline{Distribution of $M_n$}:
The CDF of $M_n$ is given by:
\[ F_{M_n}(x) = P(M_n \leq x) = (P(X_1 \leq x))^n = (1 - e^{-x})^n. \]

\underline{Probability for $M_n$}:
For large $n$ and letting $x = (1 + \epsilon) \log n$, the probability $M_n \leq (1 + \epsilon) \log n$ is:
\[ P(M_n \leq (1+\epsilon)\log n) = (1 - n^{-(1+\epsilon)})^n. \]
Using the approximation $(1 - \frac{1}{n^{1+\epsilon}})^n \to e^{-n^{-\epsilon}} \approx 1$ for large $n$, this probability approaches 0.

On the other hand, for $x = (1 - \epsilon) \log n$, the probability:
\[ P(M_n \leq (1-\epsilon)\log n) = (1 - n^{-(1-\epsilon)})^n \approx e^{-n^{\epsilon}}, \]
which approaches 0 for any $\epsilon > 0$.

\underline{Almost Sure Convergence}:
By this argument, $\frac{M_n}{\log n}$ does not deviate from 1 as $n$ becomes large, meaning:
\[ P\left(\frac{M_n}{\log n} \not\rightarrow 1\right) = 0. \]
Thus, by the Squeeze Theorem and convergence in probability, $\frac{M_n}{\log n} \rightarrow 1$ almost surely as $n \to \infty$.

This completes both parts of the problem, proving the required properties with detailed reasoning.
\end{examplebox}

