\subsection{Example 3: A Stochastic Modeling Problem}
\begin{examplebox}[Problem Statement]
Consider an inventory model in which demand for a commodity arrives at the end of each day. Successive demands are i.i.d. with distribution function $F(\cdot)$. The following $(s, S)$ policy is used: if the inventory level at the beginning of a day is less than or equal to $s$, we order up to $S$, and if the level is greater than $s$ no action is taken. Orders are assumed to filled instantaneously. Let $\left\{X_{n}\right\}_{n \geq 1}$ be the inventory level at the beginning of the $n$th day, right after delivery of inventory (if any). Suppose that $X_{1}=S$.\\
(a) Prove that $X_{n}$ is regenerative with points of regeneration that are given by the order epochs.\\
(b) Let $\left\{\tau_{n}\right\}$ denote the lengths of the regenerative cycles, derive an expression for $\mathbb{E} \tau_{1}$.\\
(c) Derive an expression for $\lim _{n \rightarrow \infty} \mathbb{P}\left(X_{n} \geq k\right)$.
\end{examplebox}

\begin{examplebox}[Reference Solution]
(a) Let $T_{0}, T_{1}, T_{2}, \ldots$ be the days we make orders. Since the inventory level at the beginning of each period $\left[T_{i}, T_{i+1}\right)$ is $S$ and the demands arriving at the end of each day are independent and identically distributed, the evolution of the process $\left\{X_{n}\right\}$ during period $\left[T_{i}, T_{i+1}\right)$ has the same probabilistic behavior for all periods. That is, $X_{n}$ is regenerative with respect to $\left\{T_{n}\right\}_{n \in N_{0}}$.\\
\vspace{1em}

\noindent (b.) Let $D_{n}$ be the demand arriving at the end of the $n^{\text{th }}$ day. Assume that the inventory level at the beginning of day 1 is $X_{1}=S$. The day we make an order (day $(\tau_{1}+1)^{\text{th}}$) is the first day we find our inventory level below or equal to $s$. That is,
$$
\begin{aligned}
\tau_{1} & =\inf \left\{n: S-\sum_{i=1}^{n} D_{i} \leq s\right\} \\
& =1+\sup \left\{n: \sum_{i=1}^{n} D_{i}<S-s\right\} \\
& =1+\sum_{n=1}^{\infty} 1_{\left\{\sum_{i=1}^{n} D_{i}<S-s\right\}}.
\end{aligned}
$$
Since the indicator functions are nonnegative, Fubini's Theorem gives
$$
\mathrm{E} \tau_{1}=1+\sum_{n=1}^{\infty} \mathrm{E}\left[1_{\left\{\sum_{i=1}^{n} D_{i}<S-s\right\}}\right]=1+\sum_{n=1}^{\infty} \mathrm{P}\left\{\sum_{i=1}^{n} D_{i}<S-s\right\}.
$$
Let $F_{1}(\cdot)=F(\cdot)$ and for $n \geq 2$ let $F_{n}(x)=\mathrm{P}\left\{\sum_{i=1}^{n} D_{i} \leq x\right\}=\left(F * F_{n-1}\right)(x)$. Assuming that $F_{n}(x)$ is continuous at $x=S-s$ for all $n$, we have $\mathrm{P}\left\{\sum_{i=1}^{n} D_{i}<S-s\right\}=F_{n}(S-s)$. Therefore,
$$
\mathrm{E} \tau_{1}=1+\sum_{n=1}^{\infty} F_{n}(S-s).
$$
If for some $n, F_{n}(x)$ has a jump at $x=S-s$, then the above expression can be corrected by replacing $F_{n}(S-s)$ with $\lim _{x \uparrow(S-s)} F_{n}(x)$.\\
\vspace{1em}

\noindent (c) Consider first the case where $k \in(s, S]$. During a cycle, the length of time that the inventory level stays above $k$ is
$$
\begin{aligned}
\sum_{n=1}^{\tau_{1}} 1_{\left\{X_{n} \geq k\right\}} & =\sup \left\{n: S-\sum_{i=1}^{n-1} D_{i} \geq k\right\} \\
& =1+\sup \left\{n: \sum_{i=1}^{n} D_{i} \leq S-k\right\} \\
& \left.=1+\sum_{n=1}^{\infty} 1_{\left\{\sum_{i=1}^{n} D_{i} \leq S-k\right\}}\right\}.
\end{aligned}
$$
Since the inventory level never goes above $S$, we have $\sum_{n=1}^{\tau_{1}} 1_{\left\{X_{n} \geq k\right\}}=0$ for all $k>S$. And since our order policy is to always keep the inventory level above $s$, it follows that $\sum_{n=1}^{\tau_{1}} 1_{\left\{X_{n} \geq k\right\}}=\tau_{1}$ for all $k \leq s$. From the regenerative ratio formula,
$$
\begin{aligned}
\lim _{n \rightarrow \infty} \mathrm{P}\left\{X_{n} \geq k\right\} & =\frac{1}{\mathrm{E} \tau_{1}} \mathrm{E}\left[\sum_{n=1}^{\tau_{1}} 1_{\left\{X_{n} \geq k\right\}}\right] \\
& = \begin{cases}0, & k>S \\
\frac{1+\sum_{n=1}^{\infty} F_{n}(S-k)}{1+\sum_{n=1}^{\infty} F_{n}(S-s)}, & s<k \leq S \\
1, & k \leq s\end{cases}
\end{aligned}
$$
\end{examplebox}

