\section{Proofs and derivations}

\subsection{Derivation of drift and diffusion coefficients for SDB}

We begin with deriving the drift and diffusion coefficients $\mathbf{F}_t, \mathbf{G}_t$ of SDB (\cref{eq:sdb_drift,eq:sdb_diffusion}) by using \cref{th:sde_to_cascade} with the mean and covariance matrices $\mathbf{H}_t, \boldsymbol{\Sigma}_t$ (\cref{eq:sdb_cascade_linear,eq:sdb_cascade_covar}) of its forward process. Recall that $\mathbf{H}_t=\mathbf{A}^+\mathbf{A} + \alpha_t(\mathbf{I} - \mathbf{A}^+\mathbf{A}),
\boldsymbol{\Sigma}_t=\gamma_t\mathbf{A}^+\boldsymbol{\Sigma}{\mathbf{A}^{+}}^\top + \beta_t(\mathbf{I} - \mathbf{A}^+\mathbf{A})$. Following \cref{th:sde_to_cascade}, we obtain
\begin{subequations}
\begin{align}
\mathbf{A}^+\mathbf{A}\mathbf{F}_t=&\frac{\diff}{\diff t}\mathbf{A}^+\mathbf{A}\log{\mathbf{H}_t} = \frac{\diff}{\diff t}\mathbf{A}^+\mathbf{A} = \mathbf{0},\\
(\mathbf{I} - \mathbf{A^+}\mathbf{A})\mathbf{F}_t=&\frac{\diff}{\diff t}\log{\alpha_t}(\mathbf{I} - \mathbf{A^+}\mathbf{A}),\\
\frac{\diff}{\diff t}\mathbf{A}^+\mathbf{A} \boldsymbol{\Sigma}_t=&\frac{\diff\gamma_t}{\diff t}\mathbf{A}^+\boldsymbol{\Sigma}\mathbf{A}^{+^\top},\\
\frac{\diff}{\diff t}(\mathbf{I - \mathbf{A}^+\mathbf{A})}\boldsymbol{\Sigma}_t =& \frac{\diff \beta_t}{\diff t}(\mathbf{I} - \mathbf{A}^+\mathbf{A}).
\end{align}
\end{subequations}
Moreover, note that $\mathbf{F}_t^\top=\mathbf{F}_t,\boldsymbol{\Sigma}_t^\top=\boldsymbol{\Sigma}_t$ due to the symmetry of the range and null space projections, and $\mathbf{F}_t\boldsymbol{\Sigma}_t=\boldsymbol{\Sigma}_t\mathbf{F}_t$ since $\mathbf{F}_t$ only affects the null space and $(\mathbf{I} - \mathbf{A}^+\mathbf{A})^2=(\mathbf{I} - \mathbf{A}^+\mathbf{A})$ (idempotent). Following \cref{th:sde_to_cascade},
\begin{subequations}
    \begin{align}
        \mathbf{F}_t=&\frac{\diff}{\diff t}\log{\alpha}_t(\mathbf{I} - \mathbf{A}^+\mathbf{A}),\\
        \mathbf{G}_t\mathbf{G}_t=&\frac{\diff \boldsymbol{\Sigma}_t}{\diff t} - \mathbf{F}_t\boldsymbol{\Sigma}_t-\boldsymbol{\Sigma}_t\mathbf{F}_t^\top\\=&
        \frac{\diff \boldsymbol{\Sigma}_t}{\diff t} - 2\mathbf{F}_t\boldsymbol{\Sigma}_t\\
        =&\frac{\diff \gamma_t}{\diff t}\mathbf{A}^+\boldsymbol{\Sigma}\mathbf{A}^{+^\top} + \left(\frac{\diff \beta_t}{\diff t} - 2\beta_t \frac{\diff}{\diff t}\log{\alpha_t}\right)(\mathbf{I} - \mathbf{A}^+\mathbf{A}).
    \end{align}
\end{subequations}

\subsection{Proof of \cref{th:ot_ode}}
We begin by recalling two propositions of \citet{liu20232} using our notation, which will serve as the basis of the proof.

\begin{proposition}\textbf{(Analytic posterior given boundary pair) \citep{liu20232}}
The posterior of \cref{eq:linear_forward_sde} given some boundary pair $(\mathbf{x}_0, \mathbf{x}_1)$ admits an analytic form:
\begin{equation}
    p(\mathbf{x}_t \mid \mathbf{x}_0, \mathbf{x}_1)=\boldsymbol{\mathcal{N}}(\boldsymbol{\mu}_t(\mathbf{x}_0, \mathbf{x}_1), \boldsymbol{\Sigma}_t),
    \label{eq:i2sb_posterior}
\end{equation}
where $\boldsymbol{\mu}_t=\frac{\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\mathbf{x}_0 + \frac{\sigma_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\mathbf{x}_1,\boldsymbol{\Sigma}_t=\frac{\sigma_t^2\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\mathbf{I}$ and $\sigma_t^2=\int_0^tg^2(\tau)\diff\tau, \bar{\sigma}_t^2=\int_t^1=g^2(\tau)\diff\tau$ with $\boldsymbol{G}_t=g(t)\mathbf{I}$.
\label{prop:i2sb_posterior}
\end{proposition}

\begin{proposition}\textbf{(Optimal Transport ODE; OT-ODE) \citep{liu20232}}
When $g^2(t)\to 0$, the SDE between ($\mathbf{x}_0, \mathbf{x}_1$) reduces to an ODE:
\begin{equation}
    \diff \mathbf{x}_t=\mathbf{v}_t(\mathbf{x}_t\mid \mathbf{x}_0)\diff t,
\end{equation}
where $\mathbf{v}_t(\mathbf{x}_t\mid \mathbf{x}_0)=\frac{g^2(t)}{\sigma_t^2}(\mathbf{x}_t - \mathbf{x}_0)$ whose solution is the posterior mean of \cref{eq:i2sb_posterior}.
\label{prop:i2sb_ot_ode}
\end{proposition}

Consider the null space part of $\mathbf{x}_t$ given by mean and covariance matrices from \cref{eq:sdb_cascade_linear,eq:sdb_cascade_covar} with $\alpha_t=\frac{\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2},\beta_t=\frac{\sigma_t^2\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}$ for $\sigma_t^2=\int_0^t g^2(\tau)d\tau, \bar{\sigma}_t^2=\int_t^1 g^2(\tau)d\tau$, where $g(t)$ is the null space diffusion coefficient given by \cref{eq:sdb_diffusion}, \ie, $g(t)=\left(\frac{\diff \beta_t}{\diff t} - 2\beta_t \frac{\diff}{\diff t}\log{\alpha_t}\right)^{\frac{1}{2}}$:
\begin{equation}
(\mathbf{I} - \mathbf{A}^+ \mathbf{A})\mathbf{x}_t=\frac{\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}(\mathbf{I} - \mathbf{A}^+ \mathbf{A})\mathbf{x}_0 + \left(\frac{\sigma_t^2\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\right)^{\frac{1}{2}}(\mathbf{I} - \mathbf{A}^+ \mathbf{A})\boldsymbol{\epsilon}
\end{equation}
for $\boldsymbol{\epsilon}\sim\boldsymbol{\mathcal{N}}(\mathbf{0}_{d}, \mathbf{I}_{d\times d}).$ Note that the null space part of $\mathbf{x}_1$, being the PR of $\mathbf{x}_0$, is zeroed out, \ie, $(\mathbf{I} - \mathbf{A}^+\mathbf{A})\mathbf{x}_1=(\mathbf{I} - \mathbf{A}^+\mathbf{A})\mathbf{0}_{d\times d}.$ This allows us to artificially rewrite $\mathbf{x}_t$ as
\begin{equation}
(\mathbf{I} - \mathbf{A}^+ \mathbf{A})\mathbf{x}_t=(\mathbf{I} - \mathbf{A}^+ \mathbf{A})\left(\frac{\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\mathbf{x}_0 + \frac{\sigma_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\mathbf{0}_{d\times d}\right) + \left(\frac{\sigma_t^2\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\right)^{\frac{1}{2}}(\mathbf{I} - \mathbf{A}^+ \mathbf{A})\boldsymbol{\epsilon}.
\end{equation}
Equivalently, $(\mathbf{I} - \mathbf{A}^+\mathbf{A})\mathbf{x}_t\sim\boldsymbol{\mathcal{N}}((\mathbf{I} - \mathbf{A}^+ \mathbf{A})\left(\frac{\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\mathbf{x}_0 + \frac{\sigma_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\mathbf{x}_1\right),\frac{\sigma_t^2\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}(\mathbf{I} - \mathbf{A}^+ \mathbf{A}))$. Hence, the posterior mean of SDB (SB) takes the form stated in \cref{prop:i2sb_posterior} and \cref{prop:i2sb_ot_ode} can be applied directly to the null space part.

As a final remark, we note that, up to this point, the definition of $g(t)$ is interdependent with that of $\alpha_t$ and $\beta_t$. It is not immediately clear that defining $\alpha_t, \beta_t$ as in \cref{th:ot_ode} fulfills $g^2(t)=\frac{\diff \beta_t}{\diff t} - 2\beta_t \frac{\diff}{\diff t}\log{\alpha_t}$. We now show that this property is indeed satisfied.

Denote by $C=\sigma_t^2 + \bar{\sigma}_t^2$ and observe that $\beta_t=\sigma_t^2\alpha_t,\bar{\sigma}_t^2=C - \sigma_t^2,\frac{\diff\sigma_t^2}{\diff t}=g^2(t)$. Then,
\begin{subequations}
    \begin{align}
        \frac{\diff}{\diff t}\log{\alpha_t}=&\frac{\diff}{\diff t} \log{\frac{\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}}\\
        =&\frac{\diff}{\diff t}\left( \log{\bar{\sigma}_t^2} - \log{C} \right)\\
        =&\frac{g^2(t)}{\bar{\sigma}_t^2},\\
        \frac{\diff \beta_t}{\diff t} =& \frac{\diff}{\diff t} (\frac{\sigma_t^2\bar{\sigma}_t^2}{\bar{\sigma}_t^2+ \sigma_t^2})\\
        =& \frac{\diff}{\diff t} \left( \frac{\sigma_t^2(C - \sigma_t^2)}{C}\right)\\
        =& \frac{1}{C}\frac{\diff}{\diff t}\left( C\sigma_t^2 - \sigma_t^4\right)\\
        =& g^2(t) - \frac{2}{C}\sigma_t^2g^2(t)\\
        =& g^2(t)(1 - \frac{2}{C}\sigma_t^2).
    \end{align}
\end{subequations}
By substituting these into the definition of $g^2(t)$, we obtain
\begin{subequations}
    \begin{align}
        \frac{\diff \beta_t}{\diff t} - 2\beta_t \frac{\diff}{\diff t}\log{\alpha_t}=&\frac{\diff}{\diff t}(\sigma_t^2 \alpha_t) - 2\sigma_t^2\alpha_t\frac{\diff}{\diff t}\log{\alpha_t}\\
        =&\alpha_t\frac{\diff \sigma_t^2}{\diff t} + \sigma_t^2\frac{\diff \alpha_t}{\diff t} - 2\sigma_t^2\alpha_t\left( \frac{1}{\alpha_t}\frac{\diff\alpha_t}{\diff t}\right)\\
        =&\alpha_tg^2(t) - \sigma_t^2\frac{\diff\alpha_t}{\diff t}\\
        =&\left( 1 - \frac{\sigma_t^2}{C}\right)g^2(t) + \frac{\sigma_t^2}{C}g^2(t)\\
        =&g^2(t),
    \end{align}
\end{subequations}
which completes the proof.

\hfill $\square$
\section{Extended related works}

\subsection{Diffusion models for inverse problems}

In recent years, deep neural networks have gained significant attention for solving various inverse problems from different perspectives \citep{9084378, chen2022simple}. Solving \cref{eq:measurement_system} can be interpreted as sampling from the posterior distribution $p(\mathbf{x} \mid \mathbf{y})$, and generative models that support conditional generation are naturally suited to this task. Diffusion models, in particular, have emerged as SOTA tools for this purpose, thanks to their flexible mathematical formulation and expressive data priors \citep{daras2024survey}. The standard approach involves extending the diffusion process to sample from $p(\mathbf{x}_0 \mid \mathbf{y})$ at $t=0$ by applying Bayes' Theorem. The conditional score function can be decomposed as $\nabla_{\mathbf{x}_t}{\log{p(\mathbf{x}_t \mid \mathbf{y})}} = \score + \nabla_{\mathbf{x}_t}{\log{p(\mathbf{y} \mid \mathbf{x}_t)}}$, where the first term, $\score$, can be approximated using a pretrained score network $\scorenet$, and the second term models the relationship between $\mathbf{x}_t$ and the measurement $\mathbf{y}$ \citep{songscore, dhariwal2021beat}. This framework has spurred considerable progress in the field, with numerous successful methods emerging \citep{kawar2022denoising, chung2022improving, chung2023diffusion, song2023pseudoinverseguided, mardanivariational, chung2024decomposed}. Since this approach does not require retraining the score network for each specific problem, we refer to these methods as \emph{unsupervised}.

Several works leverage the measurement system structure when applying pretrained diffusion models to inverse problems. \citet{wangzero} (Denoising Diffusion Null-Space Models, DDNM) restrict updates during generation to the null space component of $\mathbf{x}_t$, keeping the range part fixed. \citet{song2023pseudoinverseguided} (Pseudoinverse-Guided Diffusion Models, $\Pi \text{GDM}$) approximate the likelihood score via a vector-Jacobian product, where the score network’s Jacobian is computed with automatic differentiation, and the vector reflects the range-nullspace decomposition. \citet{Garber_2024_CVPR} (Denoising Diffusion Models with Iteratively Preconditioned Guidance, DDPG) propose a method for interpolating between pseudoinverse-based and least-squares-based conditioning.

\subsection{Diffusion and Schrödinger bridges.} 

Diffusion models, while effective for high-quality image synthesis, are limited by the simplicity of Gaussian priors for $p(\mathbf{x}_1)$. Recent developments in \emph{bridge models} \citep{sarkka2019applied} generalize the diffusion process by allowing $p(\mathbf{x}_1)$ to be an arbitrary distribution. This is especially important in image restoration tasks, where paired samples $(\mathbf{x}_0, \mathbf{x}_1)$—clean and distorted images—are available. Bridge models aim to generate samples from the posterior $p(\mathbf{x}_0 \mid \mathbf{x}_1)$ by initializing with a sample from $p(\mathbf{x}_1)$ rather than Gaussian noise. While conditioning the standard score network on $\mathbf{x}_1$ is a possible approach to achieve posterior sampling, it is often suboptimal \citep{batzolis2021conditional}.

Several methods have formulated the diffusion process as a stochastic bridge. \citet{heng2021simulating} propose a simulation-based algorithm using a fixed starting and ending point with an approximation of the true score. \citet{liu2022let} extend this with Doob's h-transform \citep{doob1984classical} to bridge distributions. Simulation-free algorithms utilizing the h-transform are presented by \citet{somnath2023aligned} and \citet{peluchetti2022nondenoising}. \citet{delbracio2023inversion} construct a Brownian Bridge for direct restoration from $\mathbf{x}_1$. More recently, \citet{zhoudenoising} introduce the DDBM framework, extending the VE and VP processes, while \citet{heconsistency} study DDBM within the consistency framework \citep{song2023consistency}. \citet{zheng2025diffusion} link DDBM to Denoising Diffusion Implicit Models \citep{song2021denoising}.

The Schrödinger Bridge (SB) problem \citep{schrodinger1932theorie}, which aligns distributions via constrained forward and reverse SDEs, has also been explored. \citet{de2021diffusion} apply Iterative Proportional Fitting (IPF) to solve the SB problem. \citet{liu20232} propose a tractable class of SBs, leading to a simulation-free algorithm (I2SB). \citet{chung2023direct} extend it with an additional guidance term. \citet{shi2024diffusion} build on IPF and introduce Iterative Markovian Fitting for SB solutions.

In a related approach, \citet{luo2023image} derive a scalar case of \cref{eq:linear_forward_sde} that incorporates the start and end points, termed the \emph{mean-reverting} SDE (IR-SDE). Through specific parameterization, they show that its score function is analytically tractable, connecting to the Ornstein-Uhlenbeck (OU) process \citep{gillespie1996exact}. \citet{yue2024image} extend this work with a generalized OU process and Doob’s h-transform (GOUB). Further extensions include \citet{luo2023refusion}, who apply IR-SDE in latent spaces, and \citet{welker22_interspeech} and \citet{richter2023speech}, who adapt similar processes for speech tasks. Recently, \citet{zhu2025unidb} unify GOUB and DDBM within the framework of stochastic optimal control.

\subsection{Baselines}

\subsubsection{Unsupervised}

We begin with describing the unsupervised baselines, which rely on solving the following scalar reverse equation:
\begin{equation}
    \diff \mathbf{x}_t = [\mathbf{f}(\mathbf{x}_t, t) - g^2(t)\nabla_{\mathbf{x}_t}\log{p(\mathbf{x}_t\mid\mathbf{y})}]\diff t + g(t)\diff \rwiener,
\end{equation}
where $\mathbf{f}$ and $g$ represent the drift and diffusion coefficients respectively, while $\mathbf{y}$ is the conditioning variable representing measurements in the inverse problem context. Unsupervised diffusion-based methods rely on decomposing the score function with Bayes' Theorem through  $\nabla_{\mathbf{x}_t}{\log{p(\mathbf{x}_t \mid \mathbf{y})}} = \score + \nabla_{\mathbf{x}_t}{\log{p(\mathbf{y} \mid \mathbf{x}_t)}}$ and approximating $\score$ with a pretrained $\scorenet$, while proposing different approaches for $\nabla_{\mathbf{x}_t}{\log{p(\mathbf{y} \mid \mathbf{x}_t)}}$. 

Diffusion Posterior Sampling (DPS, \citet{chung2023diffusion}) approximates $p(\mathbf{y}\mid \mathbf{x}_t)$ with $p(\mathbf{y}\mid\hat{\mathbf{x}}_0(\mathbf{x}_t))$, where $\hat{\mathbf{x}}_0(\mathbf{x}_t) = \mathbb{E}[\mathbf{x}_0\mid\mathbf{x}_t]=\mathbf{x}_t + g^2(t)\score$ is the Tweedie's formula \citep{robbins1992empirical}, giving an approximation of the denoised image at timestep $t$. Similarly, $\score$ is also approximated with $\scorenet$ in this case. 

Pseudoinverse-Guided Diffusion Model ($\Pi$GDM, \citet{song2023pseudoinverseguided}) proposes to approximate the loglikelihood score with $(\mathbf{y} - \mathbf{A}\hat{\mathbf{x}}_0(\mathbf{x}_t))^\top(r_t^2\mathbf{A}\mathbf{A}^\top + \sigma_{\mathbf{y}}^2\mathbf{I})^{-1}\mathbf{A}\frac{\partial\hat{\mathbf{x}}_0(\mathbf{x}_t)}{\partial\mathbf{x}_t}$, where $\sigma_{\mathbf{y}}^2\mathbf{I}$ is the measurement system covariance and $r_t^2$ is a time-dependent term that should depend on the data (Appendix A.3., \citet{song2023pseudoinverseguided}). Using automatic differentiation, one can compute $\frac{\partial\hat{\mathbf{x}}_0(\mathbf{x}_t)}{\partial\mathbf{x}_t}$. By combining it with the other terms, the entire approximation can be efficiently computed as a vector-Jacobian product.

In their basic formulation, Denoising Diffusion Null-space Models (DDNM, \citet{wangzero}) rely on approximating $p(\mathbf{x}_{t-1}\mid \mathbf{x}_t, \mathbf{y})$ using the following update rule:
\begin{equation}
    \mathbf{x}_{t-1}=\frac{\sqrt{\bar{\alpha}_{t-1}}\beta_t}{1-\bar{\alpha}_t}\hat{\mathbf{x}}_0(\mathbf{x}_t, \mathbf{y}) + \frac{\sqrt{\alpha_t}(1-\bar{\alpha}_{t-1})}{1-\bar{\alpha}_t}\mathbf{x}_t + \sigma_t\boldsymbol{\epsilon},
\end{equation}
where $\boldsymbol{\epsilon}\sim\boldsymbol{\mathcal{N}}(\mathbf{0}, \mathbf{I})$ and $\alpha_t, \beta_t$ follow the notation from the original work. This rule utilizes the range-nullspace decomposition via $\hat{\mathbf{x}}_0(\mathbf{x}_t, \mathbf{y})=\mathbf{A}^+\mathbf{y} + (\mathbf{I} - \mathbf{A}^+\mathbf{A})\hat{\mathbf{x}}_0(\mathbf{x}_t)$, which preserves the true range space component, while updating the null space part with Tweedie's estimate.

\subsubsection{Supervised}

We proceed with a description of baseline supervised bridge methods. All of these approaches assume a stochastic process conditioned on both the starting and ending point with the following forward and reverse equations:
\begin{subequations}
\begin{align}
    \diff \mathbf{x}_t =& \mathbf{f}(\mathbf{x}_t, \mathbf{x}_T, t, T)\diff t + g(t)\diff \wiener,\\
    \diff \mathbf{x}_t =& \mathbf{f}'(\mathbf{x}_t, \mathbf{x}_T, t, T)\diff t + g(t)\diff \rwiener,
\end{align}
\end{subequations}
where $\mathbf{f},\mathbf{f}'$ represent general drift coefficients respectively for the forward and reverse equation, $g$ is the diffusion coefficient and $\mathbf{x}_T$ represents the endpoint for the initial $\mathbf{x}_0$.

Image-to-Image Schrodinger Bridges (I2SB, \citet{liu20232}) formulate the distribution of $\mathbf{x}_t$, given starting and ending points $\mathbf{x}_0, \mathbf{x}_T$, as $p(\mathbf{x}_t\mid\mathbf{x}_0,\mathbf{x}_T) = \boldsymbol{\mathcal{N}}(\frac{\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\mathbf{x}_0 + \frac{\sigma_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\mathbf{x}_T, \frac{\sigma_t^2\bar{\sigma}_t^2}{\bar{\sigma}_t^2 + \sigma_t^2}\mathbf{I})$, where $\sigma_t^2=\int_0^tg^2(\tau)\diff\tau, \bar{\sigma}_t^2=\int_t^1g^2(\tau)\diff\tau$ and show its equivalence to DDPM posterior sampling \citep{ho2020denoising}.

Image Restoration SDE (IR-SDE, \citet{luo2023image}) is based on formulating the forward and reverse equations as
\begin{subequations}
    \begin{align}
        \diff \mathbf{x}_t =& \theta_t(\mathbf{x}_T - \mathbf{x}_t)\diff t + \sigma(t)\diff \wiener,\\
        \diff \mathbf{x}_t =& [\theta_t(\mathbf{x}_T - \mathbf{x}_t) - \sigma^2(t)\score]\diff t + \sigma(t)\diff \rwiener,
    \end{align}
\end{subequations}
where $\theta_t=\frac{\sigma^2_t}{\lambda^2},\bar{\theta}_t=\int_0^t{\theta_\tau}d\tau$ and $\lambda$ is a predefined constant. At $t=1$, IR-SDE arrives at a Gaussian distribution (with non-zero covariance) centered at $\mathbf{x}_T$.

Generalized Ornstein-Uhlenbeck Bridges (GOUB, \citet{yue2024image}) show IR-SDE as a special case of their framework by incorporating the Doob's h-transform \citep{doob1984classical}, which pulls the process towards the desired endpoint. Formally, it is defined as $\mathbf{h}(\mathbf{x}_t, t, \mathbf{x}_T, T)=\nabla_{\mathbf{x}_t}\log{p(\mathbf{x}_T\mid\mathbf{x}_t)}$ and incorporated into the forward and reverse equations:
\begin{subequations}
    \begin{align}
        \diff \mathbf{x}_t=&\left((\theta_t + g^2(t) \frac{e^{-2 \bar{\theta}_{t:T}}}{\bar{\sigma}_{t:T}^{2}})(\mathbf{x}_T - \mathbf{x}_t)\right)\diff t + g(t)\diff \wiener,\\
        \diff \mathbf{x}_t=&\left((\theta_t + g^2(t) \frac{e^{-2 \bar{\theta}_{t:T}}}{\bar{\sigma}_{t:T}^{2}})(\mathbf{x}_T - \mathbf{x}_t) - g^2(t)\nabla_{\mathbf{x}_t}\log{p(\mathbf{x}_t\mid \mathbf{x}_T)}\right)\diff t + g(t)\diff \rwiener,
    \end{align}
\end{subequations}
where $\theta_t=\frac{g^2(t)}{2\lambda^2},\bar{\theta}_{s:t}=\int_s^t\theta_\tau d\tau,\bar{\sigma}_{s:t}^2=\frac{g^2(t)}{2\theta_t}(1 - e^{-2\bar{\theta}_{s:t}})$ for a predefined constant $\lambda$.

Denoising Diffusion Bridge Model, (DDBM, \citet{zhoudenoising}) also utilize the h-transform, but instead show how to adapt prior unconditional processes, which map images to Gaussian noise, to construct a bridge between arbitrary distributions given paired data:
\begin{subequations}
\begin{align}
    \diff \mathbf{x}_t =& [\mathbf{f}(\mathbf{x}_t, t) + g^2(t)\mathbf{h}(\mathbf{x}_t, t, \mathbf{x}_T, T)]\diff t + g(t)\diff \wiener,\\
    \diff \mathbf{x}_t =& [\mathbf{f}(\mathbf{x}_t, t) - g^2(t)\left(\nabla_{\mathbf{x}_t}\log{p(\mathbf{x}_t\mid \mathbf{x}_T)} - \mathbf{h}(\mathbf{x}_t, t, \mathbf{x}_T, T)\right)]\diff t + g(t)\diff \rwiener,
\end{align}
\end{subequations}
where $\mathbf{f}(\mathbf{x}_t, t), g(t)$ follow the original image-to-noise process.

\section{Extended methodology}

\subsection{Network parameterization}

In a scalar setting, various reparameterizations of the score function were shown to provide different trade-offs in the final performance \citep{ho2020denoising}. For example, the network could instead predict the added noise directly, which is bijectively obtained from the score. As these reparameterizations are related through simple scalar functions, one can choose them freely without additional considerations. In the matrix-valued setting, however, the choice of a parameterization is more subtle. In this case, observe that $\score=-\boldsymbol{\Sigma}_t^{-1}(\mathbf{x}_t - \mathbf{H}_t\mathbb{E[}\mathbf{x}_0 \mid \mathbf{x}_t])$. Training a score-prediction model hence requires access to the inverse of $\boldsymbol{\Sigma}_t$, which may in general be costly to obtain. By properly choosing the form of $\gamma_t$ and $\beta_t$, one can show that $\mathbf{G}_t\mathbf{G}_t^\top\score=(f_t\mathbf{I} - 2\mathbf{F}_t)(\mathbf{H}_t\mathbb{E}[\mathbf{x}_0 \mid \mathbf{x}_t] - \mathbf{x}_t)$ for some function $f_t$, \ie, an $\mathbf{x}_0$-prediction model alleviates the need for computing $\boldsymbol{\Sigma}_t^{-1}$. Therefore, we treat this parameterization as the default one for SDB.

\subsection{Nonlinear measurement systems}

While not the focus of this work, inverse problems with nonlinear system response $\mathcal{\mathbf{A}}$ may also be considered, \eg, in the problem of GAN inversion \citep{creswell2018inverting}. Assuming that $\mathcal{\mathbf{A}}$ is differentiable, it may be locally linearized using Taylor expansion as $\mathcal{\mathbf{A}}(\mathbf{x})\approx\mathcal{\mathbf{A}}(\mathbf{x}_0) + \mathcal{\boldsymbol{J}}_{\mathcal{\mathbf{A}}}\mathbf{x}_0(\mathbf{x} - \mathbf{x}_0)$ around some point $\mathbf{x}_0$, where $\mathcal{\boldsymbol{J}}_{\mathcal{\mathbf{A}}}$ is the Jacobian of $\mathcal{\mathbf{A}}$. To adapt SDB to such cases, one can use $\mathcal{\boldsymbol{J}}_{\mathbf{A}}$ as a local linear approximation of $\mathbf{A}$ and treat it instead as the system response matrix. We consider further study of such models as future work.

\subsection{Pseudocode}
We provide pseudocode for SDB for both training and Euler-Maruyama sampling in \cref{alg:sdb_training} and \cref{alg:sdb_sampling} respectively.

\begin{algorithm}
\caption{SDB Training}
\label{alg:sdb_training}
\begin{algorithmic}[1]
\Require $p(\mathbf{x}_0), p(t), \mathbf{A}, \mathbf{A}^+, \boldsymbol{\Sigma}^{1/2}, \alpha_t, \beta_t, \gamma_t, \mathcal{\boldsymbol{D}}_{\boldsymbol{\theta}}$
\For{each iteration}
    \State $\mathbf{x} \sim p(\mathbf{x})$
    \State $t \sim p(t)$
    \State $\boldsymbol{\epsilon} \sim \mathcal{N}(\mathbf{0}, \mathbf{I}) \in \mathbb{R}^{m}$
    \State $\boldsymbol{\epsilon}' \sim \mathcal{N}(\mathbf{0}, \mathbf{I}) \in \mathbb{R}^{d}$
    \State $\mathbf{x}_t \gets [\mathbf{A}^+\mathbf{A} + \alpha_t(\mathbf{I} - \mathbf{A}^+\mathbf{A})] \mathbf{x} + \gamma_t^{\frac{1}{2}}\mathbf{A}^+\boldsymbol{\Sigma}^{\frac{1}{2}}\boldsymbol{\epsilon} + \beta_t^{\frac{1}{2}}(\mathbf{I} - \mathbf{A}^+\mathbf{A})\boldsymbol{\epsilon}'$
    \State $L_\theta \gets \left\| \mathcal{\boldsymbol{D}}_{\boldsymbol{\theta}}(\mathbf{x}_t, t) - \mathbf{x} \right\|_1$
    \State $\theta \gets \text{optimizer}(\nabla_\theta L_\theta)$
\EndFor
\State \Return $\theta$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[t]
\caption{SDB Sampling (Euler-Maruyama)}
\label{alg:sdb_sampling}
\begin{algorithmic}[1]
\Require $N, \mathbf{A}, \mathbf{A}^+, \boldsymbol{\Sigma}^{1/2},\alpha_t, \beta_t, \gamma_t, \mathbf{H}_t, \mathbf{F}_t, \mathcal{\boldsymbol{D}}_{\boldsymbol{\theta}}, \mathbf{y}$
\State $t \gets 1$
\State $\Delta t \gets 1/N$
\State $\boldsymbol{\epsilon}' \sim \mathcal{N}(\mathbf{0}, \mathbf{I}) \in \mathbb{R}^{d}$
\State $\hat{\mathbf{x}} \gets \mathbf{A}^+\mathbf{y}$
\State $\mathbf{x}_t \gets \hat{\mathbf{x}} + \beta_t^{\frac{1}{2}}(\mathbf{I} - \mathbf{A}^+\mathbf{A})\boldsymbol{\epsilon}'$
\For{$i \in \{1, \ldots, N\}$}
    \State $\boldsymbol{\epsilon} \sim \mathcal{N}(\mathbf{0}, \mathbf{I}) \in \mathbb{R}^{m}$
    \State $\boldsymbol{\epsilon}' \sim \mathcal{N}(\mathbf{0}, \mathbf{I}) \in \mathbb{R}^{d}$
    \State \parbox[t]{\dimexpr\linewidth-\algorithmicindent}{$\mathbf{x}_{t - \Delta t} \gets \mathbf{x}_t + \Delta t \left[ (f_t\mathbf{I} - 2\mathbf{F}_t)(\mathbf{H}_t\mathcal{\boldsymbol{D}}_{\boldsymbol{\theta}}(\mathbf{x}_t, t) - \mathbf{x}_t) - \mathbf{F}_t\mathbf{x}_t \right] + \\ \text{\hspace{4em}}\Delta t^{1/2} \left[ \left( \frac{\diff \gamma_t}{\diff t}\right)^{\frac{1}{2}} \mathbf{A}^+\boldsymbol{\Sigma}^{\frac{1}{2}}\boldsymbol{\epsilon} + \left( \frac{\diff \beta_t}{\diff t} - 2\beta_t\frac{\diff}{\diff t}\log{\alpha_t} \right)^{\frac{1}{2}}(\mathbf{I} - \mathbf{A}^+\mathbf{A})\boldsymbol{\epsilon}'\right]$}
    \State $t \gets t - \Delta t$
\EndFor
\State \Return $\mathbf{x}_0$
\end{algorithmic}
\end{algorithm}
\vspace{-1em}
\section{Experimental setup}
\vspace{-0.5em}
\subsection{Training hyperparameters}
\vspace{-0.5em}
We follow the training procedure proposed by \citet{luo2023image}, using the ADAM optimizer \citep{kingma2017adammethodstochasticoptimization} with an initial learning rate of $1 \times 10^{-4}$, no weight decay, and $(\beta_1, \beta_2) = (0.9, 0.99)$. A multi-step learning rate scheduler is applied, halving the learning rate at the 36th, 60th, 72nd, and 90th epochs, as in the original work. All methods are trained using the $\ell_1$ loss function with a batch size of 8. To ensure fairness across methods, we evaluate each model every 16 epochs and report the performance of the best checkpoint, rather than relying solely on the final one.
\vspace{-1em}
\subsection{Computational requirements}
\vspace{-0.5em}
All experiments were conducted on a cluster of NVIDIA A100 GPUs, with each method trained using a single GPU. The approximate training times for each task are as follows: 4 hours for super-resolution, 24 hours for MRI reconstruction, 48 hours for CT reconstruction, and 72 hours for inpainting.

\section{Additional experimental results}

\subsection{Evaluation under a misspecified model (CT reconstruction)}

\Cref{fig:ct_misspecificed_model} presents the results of an analogous analysis of performance of bridge methods under a misspecified model (here in CT reconstruction task), where the first part of the experiment considers the default setting of $\sigma_1^2$ with increasing $\tau$, while the second part shows the results for $\tau=3.6$ and increasing $\sigma_1^2$. In a similar manner to \cref{sec:misspecified_model}, all SDB variants achieve a clear advantage over other bridge methods when the system's parameters are perturbed.

\begin{figure}[h]
    \centering
    \includegraphics[width=1.0\linewidth]{figures/ct_mis_model_1.pdf}
    \includegraphics[width=1.0\linewidth]{figures/ct_mis_model_2.pdf}
    \caption{Quantitative comparison of SDB (SB) with other bridge methods in a misspecified CT reconstruction setting. The \textbf{top} row evaluates bridges trained with $\tau = 3.2$, $\sigma_1^2 = 0.0001$ on data generated from systems with increasing $\tau$. The \textbf{bottom} row evaluates performance on data with $\tau=3.6$ and increasing $\sigma_1^2$. Perturbing the original system makes the problem harder in both cases.}
    \label{fig:ct_misspecificed_model}
\end{figure}

\subsection{Hyperparameter analysis}

\begin{figure}
    \centering
    \includegraphics[width=1.0\linewidth]{figures/hp_grid_1.pdf}
    \includegraphics[width=1.0\linewidth]{figures/hp_grid_2.pdf}
    \caption{\textbf{Top}: Performance heatmaps for MRI reconstruction under varying $(\epsilon_1, \epsilon_2)$, using the optimal $(b_0, b_1)$ configuration. The red box highlights the LPIPS-optimal setting. \textbf{Bottom}: Boxplots showing the best achievable performance across 64 $(b_0, b_1)$ pairs on the superresolution task, where $(\epsilon_1, \epsilon_2)$ are tuned separately for each $(b_0, b_1)$ pair.}
    \label{fig:hp_analysis}
\end{figure}

We conduct an ablation study to analyze the sensitivity of SDB to its hyperparameters. Following prior works \citep{zhoudenoising}, our stochastic process is undefined at $t = 1$, requiring sampling to begin at $t = 1 - \epsilon_1$ for some $\epsilon_1 > 0$. Similarly, we terminate sampling at $t = \epsilon_2$, where $\epsilon_2 > 0$. For SDB (VP) and SDB (VE), $\epsilon_1$ and $\epsilon_2$ are the only hyperparameters. In contrast, SDB (SB) includes an additional design choice: the shape of the null-space diffusion coefficient $g(t)$. We parameterize it as
\[
g^2(t) = \mathbbm{1}_{t \leq 0.5} \hat{g}(t) + \mathbbm{1}_{t > 0.5} \hat{g}(1 - t)
\]
where $\hat{g}(t) = (\sqrt{b_0} + t(\sqrt{b_1} - \sqrt{b_0}))^2$, which is a continuous version of the coefficient proposed by \citet{liu20232}. This introduces two additional hyperparameters, $b_0, b_1 > 0$. In the remainder of this section, we focus on SDB (SB), noting that we observed qualitatively similar trends for the VP and VE variants.

We first examine how the choice of $\epsilon_1$ and $\epsilon_2$ influences the optimal configuration of $(b_0, b_1)$ for SDB (SB) in the MRI reconstruction task. \Cref{fig:hp_analysis} (top) shows the performance trend when varying $(\epsilon_1, \epsilon_2)$. We observe a simple and stable relationship with performance, where $\epsilon_1$ has a stronger influence than $\epsilon_2$. Moreover, a broad plateau emerges, allowing for easy tuning. We also highlight the best configuration in terms of LPIPS, which lies close to the optimal Pareto frontier in this setting.

Next, we analyze the stability of SDB (SB) across different $(b_0, b_1)$ configurations. Since these values determine the shape of the variance function, the optimal $\epsilon_1, \epsilon_2$ may differ across $(b_0, b_1)$ pairs. \Cref{fig:hp_analysis} (bottom) presents boxplots of the best performance for 64 configurations of $(b_0, b_1)$ on the superresolution task. For each pair, we use grid search to identify the best $\epsilon_1, \epsilon_2$ values, leveraging the small size of the DIV2K dataset. The results reveal strong stability, with performance concentrated around the best observed value and only a few outliers.


\section{Broader impact}

By incorporating measurement system parameters into its SDE, SDB offers positive societal impacts by enabling more accurate and efficient reconstructions in critical applications such as medical imaging, remote sensing, and scientific inverse problems, thereby supporting improved diagnostics, sustainability, and broader accessibility. However, it also poses potential negative societal risks, including misuse for surveillance or de-anonymization, amplification of bias from flawed measurement models, and overreliance on plausible but incorrect outputs in high-stakes domains. Additionally, the method could be repurposed for generating deceptive content from limited data. However, SDB and prior bridge methods have not been demonstrated at industry-scale deployment levels, and in practice, they are typically suited for problem-specific applications rather than large-scale settings with vast amounts of data. This limits their potential for misuse in broader societal contexts.

