\begin{figure*}[htbp] % Use htbp for better placement control
% \begin{algorithm}[H] % Algorithm environment already creates a float
\begin{algorithm}[H] % Using [H] from algorithm package to place it "here" if possible
\caption{Hybrid Answer Scoring Algorithm (Pseudocode)}
\label{alg:scoring} % Label for the algorithm environment itself
\begin{algorithmic}[1]
\Procedure{ScoreAnswer}{predicted\_answer, ground\_truth}
    \State $pred \gets$ Normalize(\texttt{predicted\_answer}) \Comment{e.g., lowercase, trim whitespace}
    \State $gt \gets$ Normalize(\texttt{ground\_truth})

    \If{IsNumeric($pred$) \textbf{and} IsNumeric($gt$)} \Comment{Check if both are numeric}
        \State $n_{pred} \gets$ ExtractNumeric($pred$) \Comment{Handles $, $ etc.}
        \State $n_{gt} \gets$ ExtractNumeric($gt$)
        \State \Return CompareNumeric($n_{pred}$, $n_{gt}$, tolerance=$10^{-2}$) \Comment{Allows small float diff}
    \EndIf

    \If{IsList($pred$) \textbf{and} IsList($gt$)} \Comment{Check if both look like lists}
        \State $l_{pred} \gets$ SplitSortNormalizeList($pred$) \Comment{Split, normalize elements, sort}
        \State $l_{gt} \gets$ SplitSortNormalizeList($gt$)
        \If{length($l_{pred}$) $\neq$ length($l_{gt}$)}
            \State \Return \texttt{false}
        \EndIf
        \State all\_match $\gets$ \texttt{true}
        \For{i from 0 to length($l_{pred}$) - 1}
             \If{\textbf{not} ScoreAnswer($l_{pred}[i]$, $l_{gt}[i]$)} \Comment{Recursive call for elements}
                 \State all\_match $\gets$ \texttt{false}
                 \State \textbf{break}
             \EndIf
        \EndFor
        \State \Return all\_match
    \EndIf

    \Comment{Default to string comparison}
    \State $pred_{clean} \gets$ CleanString($pred$) \Comment{Remove punctuation, extra spaces}
    \State $gt_{clean} \gets$ CleanString($gt$)
    \If{$pred_{clean} = gt_{clean}$}
        \State \Return \texttt{true} \Comment{Exact match after cleaning}
    \EndIf

    \State similarity\_score $\gets$ CalculateStringSimilarity($pred_{clean}$, $gt_{clean}$) \Comment{e.g., Levenshtein ratio}
    \If{similarity\_score $> 0.95$} \Comment{Threshold for fuzzy match}
        \State \Return \texttt{true}
    \EndIf

    % Optional: Add specific word subset check if needed (e.g., ground truth is single word)
    % If IsSingleWord($gt_{clean}$) and $gt_{clean}$ in $pred_{clean}$.split():
    %    Return true

    \State \Return \texttt{false} \Comment{Default to false if no match}

\EndProcedure

\Comment{\textit{Helper functions like Normalize, IsNumeric, ExtractNumeric, CompareNumeric, IsList, SplitSortNormalizeList, CleanString, CalculateStringSimilarity are assumed.}}
\end{algorithmic}
\end{algorithm}
