    {figures/combined_ppl_final.pdf}
  \caption{Perplexity versus training steps for jigsaw puzzles and Grounding. For jigsaw puzzles, we evaluate the perplexity of corresponding training samples. As for Grounding, we simply collect rollouts from the base model.}
  \label{combined_ppl_final}
